#!/usr/bin/env bash
# One-off: thank-you portrait of the couple for the end of the invitation, from their own photo.
set -u
cd "$(git rev-parse --show-toplevel)"
OUT=WeddingSite/oneoff/out-us; REF=WeddingSite/oneoff/ref
mkdir -p "$OUT"; LOG="$OUT/log.txt"; : > "$LOG"
WHO='The attached photo shows us, the couple getting married: Georgi (tall, athletic man, short dark hair faded at the sides, neatly trimmed dark beard) and Marina (slim woman with long dark-brown hair in a sleek high ponytail, warm bright smile). Paint THESE TWO people so they are clearly recognisable: keep their faces, hair, skin tones and builds faithful to the photo. Marina wears an elegant white wedding gown (fitted bodice, soft flowing skirt, a light veil clipped behind her ponytail). Georgi, a passionate CrossFit athlete, wears a minimalist all-black CrossFit training outfit in the NOBULL style: fitted plain black training t-shirt, black training shorts, simple black-and-white training shoes; no logos and no lettering anywhere. Marina is a passionate home cook.'
STYLE='Portrait 4:5 vignette for the very end of our luxury wedding invitation website, as a warm, joyful "thank you" scene. STYLE: Indian-miniature-meets-European gouache painting with fine gold-leaf linework and hand-painted texture, matching a high-end illustrated wedding stationery suite; soft muted palette of peach, apricot, champagne gold and blush with jewel accents (soft teal sea, emerald foliage, rose pink). Golden-hour light, happy and a little playful, full-body figures. The vignette has NO hard border: all edges fade softly into plain warm cream paper colour (#FBEEE3). No text, no letters, no logos, no frame.'
run () { echo "== $1" >> "$LOG"; ASPECT=4:5 python3 WeddingSite/oneoff/gen_from_ref.py "$WHO SCENE: $2 $STYLE" "$OUT/$1.webp" "$REF/us.jpg" >> "$LOG" 2>&1; echo "exit=$?" >> "$LOG"; }
run us-a 'On the long wooden sea bridge of Burgas over the calm Black Sea, with a slender lighthouse and gulls behind: Georgi lifts Marina effortlessly in his arms in a bridal carry, proud like after a heavy lift; she laughs and holds up, on one hand, a small homemade two-tier wedding cake she baked, decorated with pink roses. At his feet a kettlebell tied with a silk ribbon and a bunch of peonies.'
run us-b 'A flower meadow high on Vitosha mountain with Sofia and the golden domes of Alexander Nevsky cathedral far below: Marina in her wedding gown stands at a rustic wooden table with a copper pot, a round golden home-baked Bulgarian loaf and bowls of fresh vegetables, stirring with a wooden spoon and offering Georgi a taste; Georgi, chalk on his hands, carries two big baskets of vegetables in a playful farmer'\''s carry, and a kettlebell filled with wildflowers stands on the table like a vase.'
run us-c 'A sunlit garden courtyard where her kitchen meets his gym: lemon trees, roses and string lights; on one side an outdoor stone kitchen with copper pans, herbs and a cooling homemade pie; on the other a wooden plyo box and a barbell wrapped in rose garlands. Marina in her wedding gown feeds Georgi a bite of food from a wooden spoon, he leans in smiling, and they hold hands.'
cat "$LOG"
